1	//! Tests for keyword abilities: flying, first strike, trample, deathtouch,
2	//! lifelink, vigilance, flash, reach, haste, defender, hexproof, intimidate.
3	
4	mod common;
5	
6	use common::*;
7	use mtg_engine::actions::{Action, Target};
8	use mtg_engine::cards::CardRegistry;
9	use mtg_engine::combat;
10	use mtg_engine::engine;
11	use mtg_engine::sba::check_state_based_actions_with_registry;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	// ── Flying ──────────────────────────────────────────────────────────
19	
20	/// A creature with flying can only be blocked by creatures with flying or reach.
21	#[test]
22	fn flying_creature_cannot_be_blocked_by_ground_creature() {
23	    let reg = registry();
24	    let mut state = game_at_step(Step::DeclareBlockers, P0);
25	
26	    // P0's attacker: Abbey Griffin (2/2 flying)
27	    let attacker = named_creature(&mut state, &reg, "Abbey Griffin", P0);
28	
29	    // P1's blocker: vanilla ground creature
30	    let blocker = ready_creature(&mut state, P1, 3, 3);
31	
32	    assert!(!combat::can_block_attacker(&state, blocker, attacker, &reg),
33	        "Ground creature should not be able to block a flyer");
34	}
35	
36	/// A creature with flying CAN be blocked by another creature with flying.
37	#[test]
38	fn flyer_can_block_flyer() {
39	    let reg = registry();
40	    let mut state = game_at_step(Step::DeclareBlockers, P0);
41	
42	    let attacker = named_creature(&mut state, &reg, "Abbey Griffin", P0);
43	    let blocker = named_creature(&mut state, &reg, "Moon Heron", P1);
44	
45	    assert!(combat::can_block_attacker(&state, blocker, attacker, &reg),
46	        "Flyer should be able to block another flyer");
47	}
48	
49	/// A creature with reach can block a flyer.
50	#[test]
51	fn reach_can_block_flying() {
52	    let reg = registry();
53	    let mut state = game_at_step(Step::DeclareBlockers, P0);
54	
55	    let attacker = named_creature(&mut state, &reg, "Moon Heron", P0);
56	    let blocker = named_creature(&mut state, &reg, "Somberwald Spider", P1);
57	
58	    assert!(combat::can_block_attacker(&state, blocker, attacker, &reg),
59	        "Spider with reach should block a flyer");
60	}
61	
62	/// A non-flying attacker CAN be blocked by any creature (flying doesn't restrict ground blocks).
63	#[test]
64	fn ground_creature_can_be_blocked_normally() {
65	    let reg = registry();
66	    let mut state = game_at_step(Step::DeclareBlockers, P0);
67	    let attacker = ready_creature(&mut state, P0, 3, 3);
68	    let blocker = ready_creature(&mut state, P1, 2, 2);
69	
70	    assert!(combat::can_block_attacker(&state, blocker, attacker, &reg),
71	        "Ground creature should be blockable by anything");
72	}
73	
74	// ── Vigilance ───────────────────────────────────────────────────────
75	
76	/// Creatures with vigilance don't tap when attacking.
77	#[test]
78	fn vigilance_does_not_tap_on_attack() {
79	    let reg = registry();
80	    let mut state = game_at_step(Step::DeclareAttackers, P0);
81	
82	    let attacker = named_creature(&mut state, &reg, "Abbey Griffin", P0);
83	
84	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
85	
86	    assert!(!state.get_object(attacker).unwrap().tapped,
87	        "Creature with vigilance should not be tapped after attacking");
88	}
89	
90	/// A creature without vigilance still taps when attacking.
91	#[test]
92	fn non_vigilance_taps_on_attack() {
93	    let reg = registry();
94	    let mut state = game_at_step(Step::DeclareAttackers, P0);
95	    let attacker = ready_creature(&mut state, P0, 3, 3);
96	
97	    combat::declare_attackers(&mut state, &[(attacker, P1)], &reg);
98	
99	    assert!(state.get_object(attacker).unwrap().tapped,
100	        "Creature without vigilance should tap when attacking");
101	}
102	
103	// ── Defender ────────────────────────────────────────────────────────
104	
105	/// Creatures with defender cannot attack.
106	#[test]
107	fn defender_cannot_attack() {
108	    let reg = registry();
109	    let mut state = game_at_step(Step::DeclareAttackers, P0);
110	
111	    let defender = named_creature(&mut state, &reg, "Grave Bramble", P0);
112	
113	    let eligible = combat::eligible_attackers(&state, P0, &reg);
114	    assert!(!eligible.contains(&defender),
115	        "Creature with defender should not be eligible to attack");
116	}
117	
118	/// Creatures with defender CAN still block.
119	#[test]
120	fn defender_can_block() {
121	    let reg = registry();
122	    let mut state = game_at_step(Step::DeclareBlockers, P0);
123	
124	    let defender = named_creature(&mut state, &reg, "Grave Bramble", P1);
125	
126	    let eligible = combat::eligible_blockers(&state, P1, &reg);
127	    assert!(eligible.contains(&defender),
128	        "Creature with defender should still be eligible to block");
129	}
130	
131	// ── Haste ───────────────────────────────────────────────────────────
132	
133	/// Creatures with haste can attack the turn they enter (no summoning sickness).
134	#[test]
135	fn haste_overrides_summoning_sickness() {
136	    let reg = registry();
137	    let mut state = game_at_step(Step::DeclareAttackers, P0);
138	
139	    // Simulate a creature with haste that just entered (summoning_sick = true).
140	    // Use a creature object with haste keyword.
141	    // We don't have a haste creature card yet, so manually set the keyword.
142	    let creature = sick_creature(&mut state, P0, 3, 1);
143	    assert!(state.get_object(creature).unwrap().summoning_sick);
144	
145	    // Without haste, should not be eligible.
146	    let eligible = combat::eligible_attackers(&state, P0, &reg);
147	    assert!(!eligible.contains(&creature));
148	
149	    // Mark it as having haste via until-end-of-turn keyword.
150	    state.until_end_of_turn_keywords.push(
151	        mtg_engine::state::UntilEndOfTurnKeyword {
152	            target: creature,
153	            keyword: Keyword::Haste,
154	        }
155	    );
156	
157	    let eligible = combat::eligible_attackers(&state, P0, &reg);
158	    assert!(eligible.contains(&creature),
159	        "Creature with haste should be able to attack despite summoning sickness");
160	}
161	
162	// ── Hexproof ────────────────────────────────────────────────────────
163	
164	/// Creatures with hexproof can't be targeted by opponents' spells.
165	#[test]
166	fn hexproof_prevents_opponent_targeting() {
167	    let reg = registry();
