177	
178	    // There should NOT be a CastSpell action targeting the Stalker.
179	    let targets_stalker = legal.actions.iter().any(|a| {
180	        matches!(a, Action::CastSpell { targets, .. }
181	            if targets.iter().any(|t| matches!(t, Target::Object(id) if *id == stalker)))
182	    });
