189	    let legal2 = engine::legal_actions(&state, &reg);
190	    let targets_own = legal2.actions.iter().any(|a| {
191	        matches!(a, Action::CastSpell { targets, .. }
192	            if targets.iter().any(|t| matches!(t, Target::Object(id) if *id == stalker_p0)))
193	    });
